from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    comp_at = [[-1] * w for _ in range(h)]
    comps = []

    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            idx = len(comps)
            for y, x in cells:
                comp_at[y][x] = idx
            comps.append({
                "color": color,
                "cells": cells,
                "r0": min(y for y, x in cells),
                "r1": max(y for y, x in cells),
                "c0": min(x for y, x in cells),
                "c1": max(x for y, x in cells),
                "size": len(cells),
            })

    objects = [i for i, comp in enumerate(comps) if comp["size"] == 4]
    markers = [i for i, comp in enumerate(comps) if comp["size"] == 1]
    markers.sort(key=lambda i: comps[i]["cells"][0][1])
    sequence = [comps[i]["color"] for i in markers]

    if not objects or len(sequence) != len(objects):
        return [row[:] for row in grid]

    centers = {}
    tiles = {}
    for i in objects:
        obj = comps[i]
        centers[i] = ((obj["r0"] + obj["r1"]) / 2,
                      (obj["c0"] + obj["c1"]) / 2)

        votes = Counter()
        neighbors = []
        for r, c in obj["cells"]:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and comp_at[nr][nc] != i:
                    votes[grid[nr][nc]] += 1
                    neighbors.append((nr, nc))
        frame_color = votes.most_common(1)[0][0]
        frame_components = Counter(
            comp_at[r][c] for r, c in neighbors
            if grid[r][c] == frame_color
        )
        tiles[i] = comps[frame_components.most_common(1)[0][0]]

    xs = sorted(set(x for y, x in centers.values()))
    ys = sorted(set(y for y, x in centers.values()))
    dxs = [b - a for a, b in zip(xs, xs[1:])]
    dys = [b - a for a, b in zip(ys, ys[1:])]
    x_limit = 1.5 * min(dxs) if dxs else 0
    y_limit = 1.5 * min(dys) if dys else 0

    adjacent = {i: set() for i in objects}
    for i in objects:
        y1, x1 = centers[i]
        for j in objects:
            if i == j:
                continue
            y2, x2 = centers[j]
            if abs(y1 - y2) < 0.01 and abs(x1 - x2) <= x_limit:
                adjacent[i].add(j)
            if abs(x1 - x2) < 0.01 and abs(y1 - y2) <= y_limit:
                adjacent[i].add(j)

    def find_path(pos, prev, used, path):
        if pos == len(sequence):
            return path
        for i in objects:
            if i in used or comps[i]["color"] != sequence[pos]:
                continue
            if prev is not None and i not in adjacent[prev]:
                continue
            result = find_path(pos + 1, i, used | {i}, path + [i])
            if result is not None:
                return result
        return None

    path = find_path(0, None, set(), [])
    if path is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for a, b in zip(path, path[1:]):
        oa, ob = comps[a], comps[b]
        ta, tb = tiles[a], tiles[b]
        ya, xa = centers[a]
        yb, xb = centers[b]

        if abs(ya - yb) < 0.01:
            lo, hi = sorted((xa, xb))
            start = ta["c1"] + 1 if xa < xb else tb["c1"] + 1
            end = tb["c0"] - 1 if xa < xb else ta["c0"] - 1
            for r in range(oa["r0"], oa["r1"] + 1):
                for c in range(start, end + 1):
                    out[r][c] = oa["color"]
        else:
            start = ta["r1"] + 1 if ya < yb else tb["r1"] + 1
            end = tb["r0"] - 1 if ya < yb else ta["r0"] - 1
            for r in range(start, end + 1):
                for c in range(oa["c0"], oa["c1"] + 1):
                    out[r][c] = oa["color"]

    return out
